import { formatLocalDate } from '../../src/analytics/dates.js';

describe('formatLocalDate', () => {
  it('formats the local calendar date without converting to UTC', () => {
    const date = new Date(2024, 0, 2, 23, 30);
    expect(formatLocalDate(date)).toBe('2024-01-02');
  });

  it('pads single-digit months and days', () => {
    expect(formatLocalDate(new Date(2024, 8, 7))).toBe('2024-09-07');
  });
});
